package com.bank.notify.channel;

public class SmsChannel implements NotificationChannel {
    @Override
    public String send(String recipient, String message) {
        // SMS-specific logic: validate phone, truncate to 160 chars, call SMS gateway
        String truncated = message.length() > 160 ? message.substring(0, 157) + "..." : message;
        return "SMS sent to " + recipient + ": " + truncated;
    }

    @Override
    public String getChannelName() { return "SMS"; }
}
