    public static void main(String[] args) {
        SpringApplication.run(NotifyApplication.class, args);
    }

    // Register all channels as Spring beans:
    @Bean SmsChannel smsChannel() { return new SmsChannel(); }
    @Bean EmailChannel emailChannel() { return new EmailChannel(); }
    @Bean PushChannel pushChannel() { return new PushChannel(); }
    @Bean WhatsAppChannel whatsAppChannel() { return new WhatsAppChannel(); }
    // Adding a new channel: add ONE @Bean here. Dispatcher: ZERO changes.
