```java
// ─── File: src/test/java/com/bank/notify/PolymorphismBenefitsTest.java ───
package com.bank.notify;

import com.bank.notify.channel.*;
import com.bank.notify.dto.NotificationResult;
import com.bank.notify.service.NotificationDispatcher;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class PolymorphismBenefitsTest {

    List<NotificationChannel> allChannels = List.of(
        new SmsChannel(), new EmailChannel(), new PushChannel(), new WhatsAppChannel());
    NotificationDispatcher dispatcher = new NotificationDispatcher(allChannels);

    // ═══ BENEFIT 1: Same call, different behavior (runtime polymorphism) ═══
    @Test
    void sameCallDifferentBehavior() {
        NotificationResult sms = dispatcher.sendVia("SMS", "+91-9876543210", "Balance: Rs.125000");
        NotificationResult email = dispatcher.sendVia("EMAIL", "rajesh@bank.com", "Balance: Rs.125000");

        assertThat(sms.result()).contains("SMS sent");
        assertThat(email.result()).contains("Email sent");
        // Same sendVia() call → different results based on channel type
    }

    // ═══ BENEFIT 2: Open/Closed — new channel, zero changes ═══
    @Test
    void openClosed_addWhatsAppWithoutChangingAnything() {
        // WhatsAppChannel was added AFTER the system was built.
        NotificationResult wa = dispatcher.sendVia("WHATSAPP", "+91-9876543210", "Your OTP: 123456");
        assertThat(wa.result()).contains("WhatsApp sent");
        // NotificationDispatcher: ZERO changes.
        // SmsChannel, EmailChannel: ZERO changes.
        // Open/Closed Principle proven!
    }

    // ═══ BENEFIT 3: Generic loop — broadcast to ALL channels ═══
    @Test
    void genericLoop_broadcastToAll() {
        List<NotificationResult> results = dispatcher.broadcast("+91-9876543210", "Account frozen!");
        assertThat(results).hasSize(4);  // SMS + Email + Push + WhatsApp
        assertThat(results).extracting(NotificationResult::channel)
            .containsExactly("SMS", "EMAIL", "PUSH", "WHATSAPP");
        // ONE loop in dispatcher. FOUR different behaviors. No if-else!
    }

    // ═══ BENEFIT 4: Eliminates if-else chain ═══
    @Test
    void eliminatesIfElseChain() {
        // WITHOUT polymorphism: dispatcher would have:
        // if ("SMS".equals(type)) sendSms(msg);
        // else if ("EMAIL".equals(type)) sendEmail(msg);
        // else if ("PUSH".equals(type)) sendPush(msg);
        // else if ("WHATSAPP".equals(type)) sendWhatsApp(msg);
        // ...growing with every new channel!

        // WITH polymorphism: channel.send(recipient, message)
        // ONE line. No if-else. JVM dispatches at runtime.
        for (NotificationChannel channel : allChannels) {
            String result = channel.send("+91-9876543210", "Test");
            assertThat(result).isNotBlank();
        }
    }

    // ═══ COMPILE-TIME POLYMORPHISM: overloaded send ═══
    @Test
    void compileTimePolymorphism_overloadedSend() {
        SmsChannel sms = new SmsChannel();

        // Overload 1: send(recipient, message)
        String r1 = sms.send("+91-9876543210", "Hello");

        // Overload 2: send(recipient, message, subject) — default method on interface
        String r2 = sms.send("+91-9876543210", "Hello", "ALERT");

        assertThat(r1).contains("Hello");
        assertThat(r2).contains("[ALERT] Hello");
        // Same name "send" — compiler picks based on argument count. Compile-time polymorphism.
    }
}
```
